rendersuspenselistrows(St, CreatePendingSegment, CreateSuspenseListRow, FinishSuspenseListRow, PushSegmentFinale,
                       PushTreeContext, RenderNode, ResumeNode, Frame, Args) ->
  case Args of
    [P0 | R0] ->
      case R0 of
        [P1 | R1] ->
          case R1 of
            [P2 | R2] ->
              case R2 of
                [P3 | R3] ->
                  case R3 of
                    [P4 | _W] ->
                      rendersuspenselistrows_direct(St, CreatePendingSegment, CreateSuspenseListRow,
                                                    FinishSuspenseListRow, PushSegmentFinale, PushTreeContext,
                                                    RenderNode, ResumeNode, P0, P1, P2, P3, P4);
                    [] ->
                      rendersuspenselistrows_direct(St, CreatePendingSegment, CreateSuspenseListRow,
                                                    FinishSuspenseListRow, PushSegmentFinale, PushTreeContext,
                                                    RenderNode, ResumeNode, P0, P1, P2, P3, undefined)
                  end;
                [] ->
                  rendersuspenselistrows_direct(St, CreatePendingSegment, CreateSuspenseListRow, FinishSuspenseListRow,
                                                PushSegmentFinale, PushTreeContext, RenderNode, ResumeNode, P0, P1, P2,
                                                undefined, undefined)
              end;
            [] ->
              rendersuspenselistrows_direct(St, CreatePendingSegment, CreateSuspenseListRow, FinishSuspenseListRow,
                                            PushSegmentFinale, PushTreeContext, RenderNode, ResumeNode, P0, P1,
                                            undefined, undefined, undefined)
          end;
        [] ->
          rendersuspenselistrows_direct(St, CreatePendingSegment, CreateSuspenseListRow, FinishSuspenseListRow,
                                        PushSegmentFinale, PushTreeContext, RenderNode, ResumeNode, P0, undefined,
                                        undefined, undefined, undefined)
      end;
